    fn person_schema() -> Arc<Schema> {
        Arc::new(Schema::new(vec![
            Field::new("id", DataType::Utf8, false),
            Field::new("age", DataType::Int32, true),
        ]))
    }

    fn person_batch(rows: &[(&str, Option<i32>)]) -> RecordBatch {
        let ids: Vec<&str> = rows.iter().map(|(id, _)| *id).collect();
        let ages: Vec<Option<i32>> = rows.iter().map(|(_, age)| *age).collect();
        RecordBatch::try_new(
            person_schema(),
            vec![
                Arc::new(StringArray::from(ids)),
                Arc::new(Int32Array::from(ages)),
            ],
        )
        .unwrap()
    }

    fn test_identity(table_key: &str) -> TableIdentity {
        match table_key {
            "node:Person" => TableIdentity::new(1, 11).unwrap(),
            "node:Company" => TableIdentity::new(2, 22).unwrap(),
            "edge:WorksAt" => TableIdentity::new(3, 33).unwrap(),
            other => panic!("test table '{other}' has no explicit identity"),
        }
    }

    fn make_pin(table_key: &str, _table_path: &str, expected: u64, post: u64) -> SidecarTablePin {
        let identity = test_identity(table_key);
        SidecarTablePin {
            identity,
            table_key: table_key.to_string(),
            table_path: format!(
                "memory://test-graph/{}",
                crate::db::manifest::table_path_for_identity(table_key, identity).unwrap()
            ),
            expected_version: expected,
            post_commit_pin: post,
            confirmed_version: None,
            table_branch: None,
        }
    }

    fn bind_sidecar_pins_to_root(sidecar: &mut RecoverySidecar, root: &str) {
        for pin in &mut sidecar.tables {
            let relative =
                crate::db::manifest::table_path_for_identity(&pin.table_key, pin.identity).unwrap();
            pin.table_path = format!("{}/{relative}", root.trim_end_matches('/'));
        }
    }

    fn transaction(read_version: u64, uuid: &str) -> StagedTransactionIdentity {
        StagedTransactionIdentity {
            read_version,
            uuid: uuid.to_string(),
        }
    }

    fn open_lifecycle_v3(
        identity: TableIdentity,
        table_key: &str,
        binding: super::super::stream::StreamPhysicalBinding,
        head: super::super::stream::CurrentHeadWitness,
        epoch_floor: u64,
        enrollment_receipt: super::super::stream::EnrollmentReceipt,
    ) -> super::super::stream::StreamLifecycleEntry {
        use super::super::stream::{
            BindingReceipt, stream_graph_identity_digest, test_initial_binding_prior_chain,
        };

        let binding_scope_id = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
        let binding_receipt = BindingReceipt::new(
            stream_graph_identity_digest("domain-a").unwrap(),
            identity,
            &test_initial_binding_prior_chain(),
            binding_scope_id,
            enrollment_receipt.stream_incarnation_id.clone(),
            binding.clone(),
            "INITIAL_ENROLLMENT",
            1,
        )
        .unwrap();
        super::super::stream::StreamLifecycleEntry::new_open_enrollment(
            identity,
            table_key.to_string(),
            binding.clone(),
            binding_scope_id.to_string(),
            head,
            BTreeMap::from([(binding.shard_ids[0].clone(), epoch_floor)]),
            enrollment_receipt,
            binding_receipt.record_id.clone(),
            binding_receipt.next_chain_ref().unwrap(),
        )
        .unwrap()
    }

